package VehicleSystem {
    // 属性定义
    attribute def Mass :> Real;
    attribute def Speed :> Real;

// 端口定义
    port def FuelPort {
        in attribute fuelFlow: Real;
    }

port def ElectricPort {
        in attribute voltage: Real;
        out attribute current: Real;
    }

// 抽象部件定义
    abstract part def Vehicle {
        attribute mass: Mass;
        attribute maxSpeed: Speed;

abstract part powertrain: Powertrain[1];
        part wheels: Wheel[4];
    }

// 动力总成定义
    abstract part def Powertrain {
        port fuelIn: FuelPort;
        attribute power: Real;
    }

// 具体实现
    part def GasolineEngine :> Powertrain {
        attribute cylinders: Integer;
        attribute displacement: Real;
    }

part def ElectricMotor :> Powertrain {
        port powerIn: ElectricPort;
        attribute maxTorque: Real;
    }

---

