package OrderProcessing {
    // 数据类型定义
    item def Order {
        attribute orderId: String;
        attribute items: OrderItem[1..*];
        attribute total: Real;
    }

item def OrderItem {
        attribute productId: String;
        attribute quantity: Integer;
    }

item def PaymentInfo {
        attribute method: String;
        attribute amount: Real;
    }

item def ShippingLabel {
        attribute address: String;
        attribute trackingNumber: String;
    }

// 动作定义
    action def ReceiveOrder {
        out item order: Order;
    }

action def ValidateOrder {
        in item order: Order;
        out item validOrder: Order;
        out attribute isValid: Boolean;
    }

action def ProcessPayment {
        in item order: Order;
        in item payment: PaymentInfo;
        out attribute paymentSuccess: Boolean;
    }

